INSERT INTO "news" ("id", "content", "created_date", "image_url", "title") VALUES ('1', 'L''atelier Artisanat Aschi est fier d''annoncer sa participation au Salon National de l''Artisanat au Kram. Venez découvrir nos nouvelles pièces uniques et échanger avec nos maîtres artisans sculpteurs.', '2026-07-11T08:33:40.490Z', 'http://localhost:8081/api/uploads/0fa7f27c-eb3c-486e-84d8-150a7e0e66d6.jpg', 'Exposition Artisanale de Tunis 2026') ON CONFLICT DO NOTHING;
INSERT INTO "news" ("id", "content", "created_date", "image_url", "title") VALUES ('2', 'Depuis 1960, la transmission est au cœur de nos valeurs. Ce mois-ci, nous célébrons le parcours de nos deux nouveaux apprentis qui apprennent l''art ancestral de la sculpture sur noyer.', '2026-06-26T08:33:40.490Z', 'http://localhost:8081/api/uploads/2c4ac366-ccc4-442c-9601-57a964f0f694.jpg', 'Transmission de Savoir-Faire : Nos Jeunes Apprentis') ON CONFLICT DO NOTHING;
INSERT INTO "news" ("id", "content", "created_date", "image_url", "title") VALUES ('3', 'عالسلامتكم من أحلى البلايص في تونس', '2026-07-22T10:04:50.782Z', 'http://localhost:8081/api/uploads/26311da3-f949-4d74-8cd9-736cbe3f34a2.jpg', 'مسيكم بالخير 😊 #ديار_علي #جربة') ON CONFLICT DO NOTHING;
