INSERT INTO "testimonials" ("id", "client_name", "client_role", "content", "image_url", "type", "video_url") VALUES ('1', 'Sonia Ben Miled', 'Propriétaire de Villa, Sidi Bou Saïd', 'L''atelier Aschi a transformé notre entrée avec une porte monumentale qui suscite l''admiration de tous nos visiteurs. Le travail du bois est d''une finesse incomparable.', '/client-sonia.jpg', 'TEXT', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "testimonials" ("id", "client_name", "client_role", "content", "image_url", "type", "video_url") VALUES ('2', 'Mehdi Karoui', 'Directeur Général, Maison d''Hôtes Dar Sidi', 'Nous collaborons avec l''atelier Aschi depuis plusieurs années pour meubler nos suites. Leurs buffets et coffres apportent cette touche d''authenticité luxueuse qui ravit notre clientèle internationale.', '/client-mehdi.jpg', 'TEXT', NULL) ON CONFLICT DO NOTHING;
